typeSystemExample.source:
package main

import "fmt"

type Ordered interface{ ~int | ~float64 | ~string }

func Max[T Ordered](a, b T) T {
	if a >= b {
		return a
	}
	return b
}

func main() {
	fmt.Println(Max(3, 7))
	fmt.Println(Max(1.5, 2.8))
}

concurrencyExample.source:
package main

import "fmt"

func main() {
	ch := make(chan int, 4)
	for i := 0; i < 4; i++ {
		go func(n int) { ch <- n * n }(i)
	}
	for i := 0; i < 4; i++ {
		fmt.Printf("%d ", <-ch)
	}
}

